"""Tracing for voice input decisions."""

from typing import Literal

from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import add_event_to_current_span

TranscriptRejectionReason = Literal["dtmf_audio_input_disabled"]


def record_transcript_rejected(*, reason: TranscriptRejectionReason) -> None:
    """Record why a composed transcript was rejected before engine processing."""
    add_event_to_current_span(
        semconv.EVENT_TRANSCRIPT_REJECTED,
        {semconv.VOICE_TRANSCRIPT_REJECTION_REASON: reason},
    )
